/// Convert an input string into a simple ASCII‑art visual hash.\n///\n/// Each byte of the input is rendered as an 8‑character line where\n/// a `1` bit becomes a solid block `█` and a `0` bit becomes a space.\n/// The function is deterministic and works entirely with the Rust\n/// standard library.\npub fn generate_qr(input: &str) -> String {\n    let mut lines = Vec::new();\n    for byte in input.bytes() {\n        let mut line = String::with_capacity(8);\n        for i in (0..8).rev() {\n            if (byte >> i) & 1 == 1 {\n                line.push('█');\n            } else {\n                line.push(' ');\n            }\n        }\n        lines.push(line);\n    }\n    lines.join("\n")\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n\n    #[test]\n    fn test_single_character() {\n        // 'A' = 0b01000001 -> " █      █"\n        let result = generate_qr("A");\n        assert_eq!(result, " █      █");\n    }\n\n    #[test]\n    fn test_multiple_characters() {\n        // "AB" -> 'A' 01000001, 'B' 01000010\n        let result = generate_qr("AB");\n        let expected = " █      █\n █      █";\n        assert_eq!(result, expected);\n    }\n}\n
